zend_string* read_zip_entry_data(zval* zip_entry, zend_long len) {
    zend_string* result = NULL;
    zip_file* zf = (zip_file*) Z_RES_P(zip_entry);

    if (!zf) {
        return ZSTR_EMPTY_EX("");
    }

    if (len <= 0) {
        len = 1024;
    }

    void* buffer = emalloc(len + 1);
    if (zip_fread(zf, buffer, len) > 0) {
        ((char*)buffer)[len] = '\0';
        result = zend_string_init(buffer, len, 0);
    } else {
        result = ZSTR_EMPTY_EX("");
    }

    efree(buffer);

    if (!result) {
        return ZSTR_EMPTY_EX("");
    }

    return result;
}

zend_string* read_zip_entry_data(zval* zip_entry, zend_long len) {
    zend_string* result = NULL;
    zip_file* zf = (zip_file*)Z_RES_P(zip_entry)->ptr;

    if (!zf) {
        return zend_string_init("false", sizeof("false") - 1, 0);
    }

    if (len <= 0) {
        len = 1024;
    }

    size_t read_len;
    zval* buffer = zend_string_init(NULL, (size_t)len, 0);

    read_len = zip_fread(zf, ZSTR_VAL(buffer), len);

    if (read_len == 0) {
        result = zend_string_init("", 0, 0);
    } else if (read_len > 0) {
        result = zend_string_truncate(buffer, read_len, 0);
    } else {
        result = zend_string_init("false", sizeof("false") - 1, 0);
    }

    return result;
}

zend_string* read_zip_entry_data(zval* zip_entry, zend_long len) {
    zend_string* result = NULL;
    zip_file* zf = NULL;
    zip_int64_t bytes_read;
    char* buffer = NULL;

    if (Z_TYPE_P(zip_entry) != IS_RESOURCE) {
        return zend_string_init(NULL, 0, 0);
    }

    zf = (zip_file*)zend_fetch_resource_ex(zip_entry, "zip_file", le_zip_file);
    if (!zf) {
        return zend_string_init(NULL, 0, 0);
    }

    if (len <= 0) {
        len = 1024;
    }

    buffer = (char*)emalloc(len + 1);
    if (!buffer) {
        return zend_string_init(NULL, 0, 0);
    }

    bytes_read = zip_fread(zf, buffer, len);
    if (bytes_read < 0) {
        efree(buffer);
        return zend_string_init(NULL, 0, 0);
    }

    buffer[bytes_read] = '\0';
    result = zend_string_init(buffer, bytes_read, 0);
    efree(buffer);
    return result;
}

zend_string* read_zip_entry_data(zval* zip_entry, zend_long len) {
    zend_string *result = NULL;
    int success = 0;

    if (!ZIP_ISVALID_RESOURCE(zip_entry)) {
        return zend_false_string;
    }

    if (len == 0) {
        len = 1024;
    }

    success = zip_fread(Z_RES_P(zip_entry), (void**)&result, len);

    if (!success || result == NULL || result->len == 0) {
        return zend_empty_string();
    }

    return zend_string_dup(result, 0);
}

zend_string* read_zip_entry_data(zval* zip_entry, zend_long len) {
    zend_string* result = NULL;
    zip* zip_file = (zip*)zend_fetch_resource(NULL, zip_entry, -1, "zip entry", 0, 0);

    if (!zip_file) {
        return zend_string_init(ZSTR_VAL("false"), ZSTR_LEN("false"), 0);
    }

    if (len <= 0) {
        len = 1024;
    }

    size_t read_len = 0;
    char* data = (char*)emalloc(len + 1);
    if (zip_fread(zip_file, data, len, &read_len) == ZIP_OK) {
        data[read_len] = '\0';
        result = zend_string_init(data, read_len, 0);
    } else {
        result = zend_string_init(ZSTR_VAL(""), ZSTR_LEN(""), 0);
    }

    efree(data);
    return result;
}
